mapper.select:
SELECT *
FROM ai_runtime_publish_task
WHERE id = #{id} AND status = 'PROCESSING' AND lease_owner = #{owner}
  AND lease_until_ms >= #{nowMs}
FOR UPDATE

mapper.update:
UPDATE ai_runtime_publish_task
SET target_code = #{task.targetCode}, channel_code = #{task.channelCode}, data_id = #{task.dataId},
    group_name = #{task.groupName}, revision = #{task.revision}, content_hash = #{task.contentHash},
    updated_at_ms = #{nowMs}
WHERE id = #{task.id} AND status = 'PROCESSING' AND lease_owner = #{owner}
  AND lease_until_ms >= #{nowMs}

UPDATE ai_runtime_publish_task
SET status = 'PUBLISHED', lease_owner = NULL, lease_until_ms = 0,
    last_error = NULL, updated_at_ms = #{nowMs}
WHERE id = #{id} AND status = 'PROCESSING' AND lease_owner = #{owner}

UPDATE ai_runtime_publish_task
SET status = #{status}, attempts = #{attempts}, next_attempt_at_ms = #{nextAttemptAtMs},
    lease_owner = NULL, lease_until_ms = 0, last_error = #{error}, updated_at_ms = #{nowMs}
WHERE id = #{id} AND status = 'PROCESSING' AND lease_owner = #{owner}
  AND lease_until_ms >= #{nowMs}

UPDATE ai_runtime_publish_task
SET candidate_versions_json = #{candidateVersionsJson},
    gate_eval_run_ids_json = #{evalRunIdsJson}, gate_decision_json = #{decisionJson},
    gate_status = #{gateStatus}, gate_evaluated_at_ms = #{nowMs},
    status = #{publishStatus},
    lease_owner = CASE WHEN #{publishStatus} = 'BLOCKED' THEN NULL ELSE lease_owner END,
    lease_until_ms = CASE WHEN #{publishStatus} = 'BLOCKED' THEN 0 ELSE lease_until_ms END,
    last_error = #{error}, updated_at_ms = #{nowMs}
WHERE id = #{id} AND status = 'PROCESSING' AND lease_owner = #{owner}
  AND lease_until_ms >= #{nowMs}

mapper.select:
SELECT * FROM ai_runtime_publish_task
WHERE tenant_id = #{tenantId} AND revision = #{revision}
LIMIT 1

mapper.update:
UPDATE ai_runtime_publish_task
SET status = #{status}, updated_at_ms = #{nowMs}
WHERE tenant_id = #{tenantId} AND revision = #{revision}
  AND status IN ('PUBLISHED', 'PARTIAL', 'APPLIED', 'FAILED')
  AND (status <> 'APPLIED' OR #{status} = 'APPLIED')
